'use strict';
const table=(head,rows)=>`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const beanX=[15,20,30,40,50,60,70,80,90,95],beanY=[0,.1,.5,1.2,2,2.5,2.1,1.2,.1,0];
function chart(xs,series,ymax,ylabel,xlabel,marker=null){const X=x=>70+(x-xs[0])/(xs.at(-1)-xs[0])*570,Y=y=>280-y/ymax*210;return `<svg class="chart" viewBox="0 0 700 380" role="img" aria-label="${ylabel} in Abhängigkeit von ${xlabel}"><rect width="700" height="380" fill="white"/>${(ymax===3?[0,1/6,2/6,3/6,4/6,5/6,1]:[0,.2,.4,.6,.8,1]).map(t=>`<line class="gridline" x1="70" x2="640" y1="${Y(t*ymax)}" y2="${Y(t*ymax)}"/><text x="58" y="${Y(t*ymax)+5}" text-anchor="end">${String(+(t*ymax).toFixed(2)).replace('.',',')}</text>`).join('')}<path class="axis" fill="none" d="M70 60V280H650"/><text x="70" y="25">${ylabel}</text>${xs.map(x=>`<text x="${X(x)}" y="302" text-anchor="middle">${x}</text>`).join('')}<text x="355" y="329" text-anchor="middle">${xlabel}</text>${series.map((s,i)=>`<polyline fill="none" stroke="${s.color}" stroke-width="3" ${i?'stroke-dasharray="7 4"':''} points="${s.values.map((y,j)=>`${X(xs[j])},${Y(y)}`).join(' ')}"/>${s.values.map((y,j)=>`<circle cx="${X(xs[j])}" cy="${Y(y)}" r="4" fill="${s.color}"/>`).join('')}<line x1="${75+i*270}" x2="${100+i*270}" y1="355" y2="355" stroke="${s.color}" stroke-width="3" ${i?'stroke-dasharray="7 4"':''}/><text x="${108+i*270}" y="360">${s.label}</text>`).join('')}${marker!==null?`<line x1="${X(marker)}" x2="${X(marker)}" y1="55" y2="280" stroke="#b46b1f" stroke-width="2" stroke-dasharray="4 4"/>`:''}</svg>`}
const beans=()=>`<figure>${chart(beanX,[{label:'Bohnenpflanzen',color:'#087c88',values:beanY}],3,'Zuwachs der Trockenmasse in g','Bodenfeuchtigkeit in %')}<figcaption>Modellversuch aus AB 2. Mittelwerte nach vier Wochen; didaktisch modellierte Daten. Die Linien verbinden die Messpunkte.</figcaption></figure>`;
const beanTable=table(['Bodenfeuchte (%)',...beanX], [['Trockenmassezuwachs (g)',...beanY.map(x=>String(x).replace('.',','))]]);
const pineTable=table(['Bodenfeuchte (%)',15,30,45,60,75,90],[['Waldkiefer allein',3,6,9,10,8,4],['Waldkiefer mit Rotbuche',3,5,3,1,2,4],['Rotbuche allein',0,3,8,10,9,1],['Rotbuche mit Waldkiefer',0,3,8,9,8,1]]);
const siteTable=table(['Merkmal','A: offene Rasenfläche','B: unter Laubbäumen'],[['Licht um 12 Uhr','42.000 Lux','3.500 Lux'],['Licht im Jahresverlauf','Offen; wetter- und jahreszeitabhängig','Vor Laubaustrieb heller, im Sommer schattig'],['Temperatur um 12 Uhr','22 °C','17 °C'],['Boden','Mäßig trocken, stellenweise verdichtet','Mäßig feucht, humusreich, oberflächlich locker'],['Pflege','Alle zwei Wochen kurze Mahd','Keine regelmäßige Mahd, Laub bleibt liegen'],['Nutzung','Pausenfläche; Randstreifen veränderbar','Selten betreten; Bäume bleiben erhalten'],['Nährstoffversorgung','Nicht untersucht','Nicht untersucht']]);
const plants=table(['Pflanze','Ansprüche und Pflege','Blütezeit etwa','Nahrung für Bienen'],[['Gänseblümchen','Hell, frischer Boden; niedrige Rosette verträgt Mahd, Blüten können abgeschnitten werden','Feb.–Nov.','Nektar und Pollen'],['Breitwegerich','Hell bis teilweise beschattet, frischer Boden; tritt- und mahdtolerant','Juni–Okt.','Kein Nektar; Pollen kann gesammelt werden'],['Echter Wurmfarn','Schattig bis halbschattig, frisch bis feucht und humusreich; keine regelmäßige Mahd','Keine Blüten','Weder Nektar noch Pollen; Sporenpflanze'],['Weißklee','Hell, frischer Boden; kriechende Triebe überstehen Mahd, Blütenstände nicht immer','Mai–Sept.','Nektar und Pollen'],['Kleine Braunelle','Sonnig bis halbschattig, frisch bis feucht; Blütentriebe müssen stehen bleiben','Juni–Sept.','Nektar und Pollen'],['Geflecktes Lungenkraut','Halbschattig bis schattig, frisch bis feucht, humus- und nährstoffreich; geringe Trittbelastung','März–Mai','Nektar und Pollen']]);
window.GK={topics:[
{id:'oekosystem',title:'Ökosystem & Umweltfaktoren',short:'Ökosystem',desc:'Biotop, Biozönose und das Zusammenwirken im Aquarium.',source:'AB 1 · Ökosystem',sections:[
['Ein System aus Lebensraum und Lebensgemeinschaft',`<p><b>Ökologie</b> untersucht die Beziehungen von Lebewesen untereinander und zu ihrer Umwelt.</p><p>Ein <b>Ökosystem</b> besteht aus dem <b>Biotop</b>, der <b>Biozönose</b> und ihren Wechselwirkungen. Das Biotop ist der räumlich abgrenzbare Lebensraum mit seinen unbelebten Bestandteilen und Bedingungen. Zur Biozönose gehören alle dort lebenden Organismen verschiedener Arten.</p><p>Im Aquarium gehören Wasser, Bodengrund, Licht, Temperatur und Sauerstoffgehalt zum Biotop. Fische, Schnecken, Wasserpflanzen, Algen, Bakterien und Pilze bilden die Biozönose. Auch ein künstlich angelegtes Aquarium ist ein Ökosystem. Es muss dafür nicht unabhängig von menschlicher Pflege sein.</p>`],
['Abiotische und biotische Faktoren',`<p><b>Abiotische Faktoren</b> sind Einflüsse der unbelebten Umwelt, etwa Licht oder Temperatur. <b>Biotische Faktoren</b> entstehen durch Lebewesen, etwa Fraß, Konkurrenz oder Symbiose.</p><p>Die Ressource und die Wechselwirkung sind zu unterscheiden: Wasser ist abiotisch. Konkurrieren zwei Pflanzen um Wasser, ist diese Konkurrenz eine biotische Wechselwirkung.</p><div class="note">Eine Population umfasst die Individuen einer Art in einem Gebiet zu einer bestimmten Zeit. Die Biozönose umfasst die Lebensgemeinschaft verschiedener Arten.</div>`],
['Wechselwirkungen erklären',`<p>Licht beeinflusst die Fotosynthese von Wasserpflanzen. Dabei entsteht Sauerstoff, den unter anderem Fische für die Zellatmung benötigen. Die Organismen verändern also ihrerseits die abiotischen Bedingungen.</p><p>Eine Pfeilkette soll die Wirkung benennen: <b>mehr Licht im geeigneten Bereich → höhere Fotosyntheseleistung → stärkere Sauerstoffproduktion</b>. Daraus folgt nicht, dass der gemessene Sauerstoffgehalt immer steigt: Auch Verbrauch, Temperatur und Austausch mit der Luft wirken darauf ein.</p>`]]},
{id:'toleranz',title:'Abiotische Faktoren & Toleranzkurven',short:'Toleranzkurven',desc:'Die Bohnen-Daten auswerten und Überleben von Fortpflanzung unterscheiden.',source:'AB 2 · Wie beeinflussen abiotische Faktoren Organismen?',sections:[
['Eine Toleranzkurve lesen',`<p>Temperatur beeinflusst zum Beispiel die Aktivität einer Eidechse. Als wechselwarmes Tier hängt ihre Körpertemperatur stark von der Umgebung und ihrem Verhalten ab. Bei Kälte laufen Stoffwechselprozesse meist langsamer ab; im geeigneten Wärmebereich kann sie aktiver sein. Zu hohe Temperaturen können schädlich sein.</p><p>Eine Toleranzkurve zeigt, wie eine untersuchte Lebensleistung von der Stärke eines Umweltfaktors abhängt. Auf der x-Achse steht der Faktor mit Einheit, auf der y-Achse die gemessene Leistung. Im Bohnenversuch werden gleich alte Pflanzen vier Wochen bei verschiedenen Bodenfeuchten gehalten. Licht, Temperatur, Boden und Nährstoffangebot bleiben gleich.</p><p>Die Bodenfeuchte bezeichnet hier den mit Wasser gefüllten Anteil des Porenraums. Trockenmasse wird nach dem Entfernen des Wassers gemessen; ihr Zuwachs beschreibt neu entstandene Pflanzenmasse.</p>${beans()}${beanTable}<p>Bis 60 % steigt der Zuwachs auf 2,5 g. Danach sinkt er bis auf 0 g bei 95 %. Bei diesen Versuchsbedingungen liegt das gemessene Wachstumsoptimum bei 60 %.</p>`],
['Die Begriffe sicher unterscheiden',table(['Begriff','Bedeutung im Bohnenmodell'],[['Toleranzbereich','Überleben bei 15–95 % Bodenfeuchte.'],['Minimum / Maximum','Untere / obere Überlebensgrenze: 15 % / 95 %. Außerhalb sterben die Pflanzen dauerhaft ab.'],['Pessima','15–25 % und 85–95 %: Überleben, aber keine keimfähigen Samen.'],['Fortpflanzungsbereich','Mehr als 25 % und weniger als 85 %: Wachstum und keimfähige Samen sind möglich.'],['Optimum','Faktorwert mit höchster untersuchter Lebensleistung: 60 % für den Trockenmassezuwachs.'],['Präferendum','Besonders günstiger Bereich um das Optimum. Ohne festgelegtes Kriterium keine exakten Grenzen aus diesen Daten.']])+'<p>Die Angaben zu Überleben und Samenbildung stammen aus einer zusätzlichen längeren Beobachtung. Sie lassen sich nicht allein aus der Wachstumskurve ablesen.</p>'],
['Wachstum, Überleben und Fortpflanzung unterscheiden',`<p><b>0 g Zuwachs bedeutet nicht automatisch Tod.</b> Eine Pflanze kann überleben, ohne messbar neue Trockenmasse aufzubauen. Ebenso beweist Wachstum noch keine erfolgreiche Fortpflanzung.</p><p>„Mehr Wasser ist immer besser“ widerspricht dem Abfall der Kurve oberhalb von 60 %. Bei hoher Wassersättigung bleibt weniger luftgefüllter Porenraum. Wurzeln benötigen Sauerstoff für die Zellatmung; Sauerstoffmangel ist eine mögliche Erklärung für geringeres Wachstum.</p><p>Für einen aussagekräftigen Versuch wird ein Faktor gezielt verändert. Andere Bedingungen werden vergleichbar gehalten, mehrere Pflanzen je Stufe untersucht und die Messgrößen vorher festgelegt. Aussagen über Fortpflanzung brauchen entsprechende Beobachtungen.</p>`]]},
{id:'potenz',title:'Konkurrenz & ökologische Potenz',short:'Ökologische Potenz',desc:'Waldkiefer und Rotbuche: Wachstum, Konkurrenz und tatsächliches Vorkommen.',source:'AB 3 · Ökologische Potenz; ergänzendes Seepocken-Arbeitsblatt',sections:[
['Konkurrenz und ihre Folgen',`<p><b>Konkurrenz</b> entsteht, wenn Organismen dieselbe begrenzte Ressource nutzen. Bei Individuen derselben Art heißt sie <b>intraspezifisch</b>, bei verschiedenen Arten <b>interspezifisch</b>. Betroffen sein können Wasser, Licht, Mineralstoffe, Nahrung oder Nistplätze.</p><p>Im Modell wachsen Waldkiefer und Rotbuche getrennt oder gemeinsam. Die übrigen Versuchsbedingungen sind gleich. Die relative Wuchsleistung wird auf einer Skala von 0 bis 10 erfasst.</p>${pineTable}<p class="source">Didaktisch modellierte Werte aus AB 3; die Zahlen beschreiben Wachstum während des Versuchs.</p><p>Bei 60 % Bodenfeuchte sinkt die Wuchsleistung der Kiefer in Mischkultur von 10 auf 1. Die Buche verändert sich nur von 10 auf 9. Die Wirkung der Konkurrenz ist hier also ungleich.</p>`],
['Physiologische und ökologische Potenz',`<p>Die <b>physiologische Potenz</b> bezeichnet den Bereich eines abiotischen Faktors, in dem eine Art ohne Konkurrenz dauerhaft überleben und sich fortpflanzen kann. Die <b>ökologische Potenz</b> beschreibt dies unter Konkurrenzbedingungen.</p><p>Eine langfristige Modellkartierung zeigt: Bei 45–75 % Bodenfeuchte ist die Kiefer selten, die Buche häufig. Bei 15 % und 90 % ist die Kiefer häufig, die Buche fehlt. Dort ist die Konkurrenz durch die Buche geringer. Häufiges Vorkommen zeigt deshalb nicht automatisch das physiologische Optimum einer Art an.</p><div class="note">Kurzfristige Wuchsleistung allein bestimmt keine vollständige Potenz. Dazu braucht man Informationen über dauerhaftes Überleben und Fortpflanzung.</div>`],
['Transfer: Verbreitungsgrenzen untersuchen',`<p>Bei Seepocken in der Gezeitenzone können lange Trockenphasen die obere Verbreitungsgrenze setzen. In tieferen Bereichen kann Konkurrenz um Siedlungsraum das Vorkommen begrenzen.</p><p>Ein <b>Konkurrenz-Ausschlussversuch</b> vergleicht Flächen mit und ohne Konkurrenten. Überlebt eine Art nach dessen Entfernung besser, stützt dies eine Wirkung der Konkurrenz. Die Flächen müssen sonst vergleichbar sein. Eine Überlebensrate nach acht Wochen belegt aber noch keine erfolgreiche Fortpflanzung.</p>`]]},
{id:'nische',title:'Ökologische Nische & Koexistenz',short:'Ökologische Nische',desc:'Kohlmeise und Blaumeise teilen einen Garten und nutzen ihn unterschiedlich.',source:'AB 4 · Ökologische Nische; Informationsbereiche des Meisen-Lernprogramms',sections:[
['Lebensraum ist nicht gleich Nische',`<p>Der <b>Lebensraum</b> ist der Ort, an dem eine Art lebt. Die <b>ökologische Nische</b> umfasst die Gesamtheit ihrer Umweltansprüche und Umweltbeziehungen. Dazu gehören abiotische Bedingungen sowie Nahrung, Feinde, Konkurrenten und weitere Beziehungen.</p><p>Zwei Arten können im selben Garten leben und sich trotzdem in ihrer Nische unterscheiden. Eine Nische ist kein einzelner Ort im Baum und kein einzelnes Körpermerkmal.</p>`],
['Nischenprofile vergleichen',table(['Merkmal','Kohlmeise','Blaumeise'],[['Körperbau','Größer und schwerer','Kleiner und leichter'],['Nahrungssuche','Häufig an kräftigen inneren Ästen, auch am Boden','Häufig an feinen äußeren Zweigen und Blättern'],['Nahrung','Unter anderem Insektenlarven; auch größere Beutetiere; im Winter häufig Samen','Häufig kleine Insekten, Spinnen und andere Gliederfüßer'],['Nistkastenöffnung','Etwa 32 mm geeignet','Etwa 26–28 mm zugänglich; größere Öffnungen ebenfalls möglich']])+'<p>Diese Nutzungsmuster sind typische Schwerpunkte und keine starren Grenzen. Beide Arten können beispielsweise am Futterhaus dieselbe Nahrung nutzen.</p>'],
['Nischenüberlappung und Nischendifferenzierung',`<p><b>Nischenüberlappung</b> bedeutet teilweise gleiche Ansprüche. Sind gemeinsame Ressourcen begrenzt, kann Konkurrenz entstehen. <b>Nischendifferenzierung</b> ist die unterschiedliche Nutzung von Ressourcen, etwa verschiedener Bereiche bei der Nahrungssuche. Sie kann Konkurrenz verringern und Koexistenz begünstigen.</p><p>Der unterschiedliche Körperbau ermöglicht unterschiedliche Nutzungsschwerpunkte. Kleine Nistkastenöffnungen können der Blaumeise einen Zugang bieten, den die größere Kohlmeise nicht nutzen kann. Werden nur große Öffnungen angeboten, nimmt die Überlappung bei dieser Ressource zu.</p><p>Bei dauerhaft vollständiger Konkurrenz um dieselbe begrenzte Ressource kann eine Art verdrängt werden. Ähnliche Nahrung allein beweist aber weder identische Nischen noch einen zwingenden Konkurrenzausschluss.</p>`]]},
{id:'standort',title:'Standortbedingungen & Artvorkommen',short:'Standortanalyse',desc:'Pflanzen auswählen, Blühangebot prüfen und einen Nutzungskonflikt abwägen.',source:'AB 5 · Standortbedingungen und Artvorkommen',sections:[
['Standorte anhand von Daten vergleichen',`<p>Die Bienen-AG möchte das Nahrungsangebot auf dem Schulgelände verbessern. Dazu müssen Standortansprüche, Blütenangebot und Nutzung zusammen betrachtet werden.</p>${siteTable}<p>Die Messwerte beschreiben zunächst den Untersuchungstag. Ein einzelner Luxwert beweist keine ganzjährigen Lichtverhältnisse. Aus humusreichem Boden allein folgt kein gemessener Nährstoffgehalt.</p>`],
['Sechs Pflanzenprofile',`${plants}<p>Nektar liefert vor allem Zucker; Pollen liefert unter anderem Proteine. Pflanzenvorkommen, mögliche Blütezeit und tatsächliches Blütenangebot sind verschiedene Informationen. Werden Blüten regelmäßig abgeschnitten, kann eine Pflanze überleben, ohne zu diesem Zeitpunkt Nahrung bereitzustellen.</p>`],
['Eine Maßnahme begründet beurteilen',`<p>Ein sonniger Randstreifen mit Weißklee und Kleiner Braunelle ist eine mögliche Option, wenn Feuchte und Pflege passen. Abschnitte können zeitlich versetzt gemäht werden, sodass Blüten stehen bleiben. Die zentrale Pausenfläche bleibt nutzbar. Völliger Mahdverzicht kann dagegen hohe Gräser fördern, die niedrige Pflanzen beschatten.</p><p>Unter Laubbäumen kann Lungenkraut das Frühjahrsangebot ergänzen; die Nährstoffversorgung und mögliche Trockenphasen sind noch zu prüfen. Wurmfarn passt eher zum schattigen Standort, liefert aber direkt weder Nektar noch Pollen.</p><div class="note">Ein begründetes Urteil nennt Kriterien, Materialbelege, einen Zielkonflikt und eine Schlussfolgerung. Hier: Standorteignung, Nahrung im Jahresverlauf, Pflege und Pausennutzung. Zusätzliche Beobachtungen von Blüten und Bienenbesuchen prüfen die Wirkung.</div>`]]},
{id:'symbiose',title:'Symbiose: Grundel & Knallkrebs',short:'Symbiose',desc:'Fähigkeiten vergleichen und den gegenseitigen Nutzen erklären.',source:'AB 6 · Interspezifische Beziehungen; DOCX Grundel und Knallkrebs',sections:[
['Zwei Partner mit unterschiedlichen Fähigkeiten',`<p>Bestimmte Grundelarten und Knallkrebse leben gemeinsam in einer Höhle. Der Knallkrebs baut und unterhält sie. Beide Tiere nutzen sie als Rückzugsort. Der Krebs sieht schlecht; die Grundel besitzt ein gutes Sehvermögen und beobachtet am Eingang die Umgebung.</p><p>Außerhalb der Höhle hält der Knallkrebs mit einem Fühler Kontakt zur Grundel. Erkennt sie eine Gefahr, führt sie zitternde Bewegungen mit dem hinteren Körperabschnitt aus. Diese Bewegungen werden über den Kontakt wahrgenommen. Bei zunehmender Gefahr zieht sie sich rasch zurück.</p>`],
['Den Nutzen beider Partner belegen',`<p>Die <b>Grundel</b> erhält Zugang zu einer vom Krebs gebauten und unterhaltenen Schutzhöhle. Der <b>Knallkrebs</b> erhält durch die gut sehende Grundel Warninformationen und kann auf Gefahren reagieren.</p><p>Im hier verwendeten engeren Sinn ist <b>Symbiose</b> eine Beziehung zwischen verschiedenen Arten, von der beide Partner profitieren: <b>+/+</b>. Ein räumliches Zusammenleben allein reicht als Beleg nicht aus.</p>`],
['Beobachtung und Erklärung unterscheiden',`<p>Ein Bild kann beispielsweise den Fühlerkontakt zeigen. Es beweist für sich genommen weder ein Warnsignal noch einen Überlebensvorteil. Für die Erklärung werden Verhaltensbeobachtungen und die unterschiedlichen Fähigkeiten beider Tiere benötigt.</p><p>Eine prüfbare Vermutung wäre: Ohne Fühlerkontakt reagiert der Krebs später auf eine von der Grundel erkannte Gefahr. Ein Vergleich müsste andere Bedingungen und das Gefahrensignal gleich halten.</p>`]]},
{id:'parasitismus',title:'Parasitismus: Assel & Fisch',short:'Parasitismus',desc:'Schaden, möglichen Funktionsersatz und gesicherte Befunde auseinanderhalten.',source:'AB 7 · Interspezifische Beziehungen; DOCX Assel und Fisch',sections:[
['Wie die Assel den Fisch schädigt',`<p>Die Assel <i>Cymothoa exigua</i> befällt unter anderem Schnapperfische. Junge Asseln gelangen in den Kiemenbereich; ein Weibchen siedelt sich später im Maul an. Hakenförmige Beinenden dienen dem Festhalten.</p><p>Nach der gängigen Erklärung schädigt die angeheftete Assel die Blutversorgung der Zunge. Das Gewebe erhält weniger Sauerstoff und Nährstoffe und verkümmert. Die Assel bleibt am Zungenstumpf und Mundboden befestigt.</p><p>Als Nahrung werden Blut und Schleim beschrieben. Die genaue Ernährung im erwachsenen Stadium ist nicht abschließend geklärt.</p>`],
['Warum ein Ersatz nicht automatisch Nutzen bedeutet',`<p>Bei zwei untersuchten befallenen Fischen fehlten mehr als 90 % der Zunge. Beide hatten dennoch Nahrung aufgenommen. Dies stützt die Vermutung, dass die Assel einen Teil der mechanischen Funktion beim Festhalten von Nahrung übernehmen kann.</p><p>Es zeigt nicht, dass der befallene Fisch gegenüber einem gesunden Fisch ohne Assel einen Vorteil hat. Der Gewebeverlust bleibt ein Schaden. Die mögliche Ersatzfunktion gleicht die Beziehung nicht automatisch aus.</p>`],
['Beziehungen kriteriengeleitet einordnen',`<p>Beim <b>Parasitismus</b> profitiert der Parasit, während der Wirt geschädigt wird: <b>+/−</b>. Der Parasit nutzt den Wirt als Lebensraum und/oder Nahrungsquelle; der Wirt muss dabei nicht unmittelbar sterben.</p>${table(['Beziehung','Wirkung','Entscheidender Beleg'],[['Symbiose im engeren Sinn','+/+','Nutzen für beide Partner'],['Parasitismus','+/−','Nutzen für Parasit, Schaden für Wirt'],['Konkurrenz','−/−','Beide werden durch die gemeinsame Nutzung begrenzter Ressourcen beeinträchtigt, häufig unterschiedlich stark']])}<p>Einordnung braucht den Vergleich mit einer passenden Situation ohne Partner bzw. Befall. Ein noch lebender Wirt ist kein Beweis für Symbiose.</p>`]]}
],exercises:[],exams:[]};
const add=(topic,id,title,type,prompt,body)=>GK.exercises.push({topic,id,title,type,prompt,...body});
add('oekosystem','aquarium','Das Aquarium zuordnen','match','Ordne jeden Bestandteil dem Biotop oder der Biozönose zu.',{options:['Biotop','Biozönose'],items:[['Sauerstoffgehalt','Biotop','Der Sauerstoffgehalt ist eine unbelebte Umweltbedingung.'],['Wasserpflanzen','Biozönose','Pflanzen sind Lebewesen.'],['Bakterien im Bodengrund','Biozönose','Auch mikroskopisch kleine Lebewesen gehören zur Lebensgemeinschaft.'],['Wassertemperatur','Biotop','Temperatur ist eine abiotische Bedingung.'],['Schnecken','Biozönose','Schnecken sind Teil der Lebensgemeinschaft.'],['Mineralstoffgehalt','Biotop','Gelöste Mineralstoffe sind unbelebte Bestandteile.']]});
add('oekosystem','faktoren','Ressource oder Wechselwirkung?','match','Ordne die beschriebenen Einflüsse zu.',{options:['Abiotischer Faktor','Biotische Wechselwirkung'],items:[['Zwei Wasserpflanzen beschatten einander','Biotische Wechselwirkung','Lebewesen beeinflussen sich: Konkurrenz um Licht.'],['Die Wassertemperatur beträgt 20 °C','Abiotischer Faktor','Temperatur gehört zur unbelebten Umwelt.'],['Fische fressen kleine Schnecken','Biotische Wechselwirkung','Fraß ist eine Beziehung zwischen Organismen.'],['Zwei Pflanzen konkurrieren um Wasser','Biotische Wechselwirkung','Die Wechselwirkung bleibt biotisch, obwohl Wasser abiotisch ist.']]});
add('oekosystem','system','Ein künstliches Ökosystem?','multi','Wähle alle fachlich richtigen Aussagen aus.',{choices:[['Ein Aquarium kann trotz menschlicher Pflege ein Ökosystem sein.',true,'Entscheidend sind Biotop, Biozönose und Wechselwirkungen.'],['Biotop und Biozönose beeinflussen sich gegenseitig.',true,'Organismen verändern beispielsweise den Sauerstoffgehalt.'],['Ein Ökosystem muss ohne jeden Energieaustausch bestehen.',false,'Ökosysteme stehen im Austausch mit ihrer Umgebung.'],['Alle Fische verschiedener Arten bilden zusammen eine Population.',false,'Eine Population umfasst Individuen einer Art.']]});
add('toleranz','kurve','Die Toleranzkurve untersuchen','curve','Verschiebe den Regler. Prüfe danach die vier Angaben zur Kurve und zur zusätzlichen Langzeitbeobachtung.',{items:[['Optimum des Trockenmassezuwachses (%)',60,'Bei 60 % ist der Zuwachs mit 2,5 g maximal.'],['Unterste Bodenfeuchte mit Überleben (%)',15,'Die zusätzliche Beobachtung nennt 15 % als Minimum.'],['Oberste Bodenfeuchte mit Überleben (%)',95,'95 % ist die obere Überlebensgrenze im Modell.'],['Zuwachs bei 60 % Bodenfeuchte (g)',2.5,'Lies die y-Achse ab: 2,5 g.']]});
add('toleranz','begriffe','Die Bereiche einer Toleranzkurve','match','Ordne die Beschreibungen den passenden Begriffen zu.',{options:['Optimum','Präferendum','Pessimum','Toleranzbereich','Minimum'],items:[['Überleben möglich, aber keine keimfähigen Samen','Pessimum','Pessima liegen an den Rändern des Überlebensbereichs.'],['Faktorwert mit höchster gemessener Leistung','Optimum','Das Optimum ist ein Faktorwert, kein breiter Bereich.'],['Besonders günstiger Bereich um das Optimum','Präferendum','Exakte Grenzen brauchen ein festgelegtes Kriterium.'],['Gesamter Bereich, in dem Überleben möglich ist','Toleranzbereich','Dazu gehören auch die Pessima.'],['Untere Grenze des Überlebensbereichs','Minimum','Unterhalb des Minimums ist dauerhaftes Überleben unmöglich.']]});
add('toleranz','versuch','Was belegen die Daten?','multi','Wähle alle Aussagen, die mit dem Bohnenmodell vereinbar sind.',{choices:[['0 g Zuwachs bei 15 % beweist den Tod der Pflanze.',false,'Die Langzeitbeobachtung zeigt dort Überleben ohne keimfähige Samen.'],['Licht und Temperatur sollen im Feuchteversuch vergleichbar sein.',true,'Sonst wäre der Einfluss der Bodenfeuchte schwerer zu isolieren.'],['Ein höherer Wasseranteil kann den luftgefüllten Porenraum verringern.',true,'Wurzeln benötigen Sauerstoff für die Zellatmung.'],['Die Präferendumsgrenzen lassen sich aus der Kurve auf exakt 40 und 80 % festlegen.',false,'Ein entsprechendes Abgrenzungskriterium fehlt.'],['Für Aussagen über Fortpflanzung sind Daten zur Samenbildung nötig.',true,'Wachstum allein reicht nicht.']]});
add('potenz','kiefer','Den Konkurrenzeffekt berechnen','numeric','Berechne anhand der Tabelle die Abnahme der Wuchsleistung der Kiefer: Wert allein minus Wert mit Buche.',{material:pineTable+'<p class="source">Relative Wuchsleistung (0–10), didaktisch modellierte Daten.</p>',items:[['Abnahme bei 45 % Bodenfeuchte',6,'9 − 3 = 6 Einheiten.'],['Abnahme bei 60 % Bodenfeuchte',9,'10 − 1 = 9 Einheiten.'],['Abnahme bei 90 % Bodenfeuchte',0,'4 − 4 = 0 Einheiten.']]});
add('potenz','potenzbegriffe','Welcher Befund trägt welche Aussage?','match','Ordne die Untersuchungen ihrer Aussagekraft zu.',{options:['Physiologische Potenz','Ökologische Potenz','Nur kurzfristige Wuchsleistung'],items:[['Dauerhaftes Überleben und Fortpflanzung ohne Konkurrenz untersucht','Physiologische Potenz','Beide Kriterien werden ohne Konkurrenz geprüft.'],['Dauerhaftes Überleben und Fortpflanzung unter Konkurrenz untersucht','Ökologische Potenz','Die Konkurrenzbedingungen gehören zur Aussage.'],['Vier Wochen lang nur den Zuwachs gemessen','Nur kurzfristige Wuchsleistung','Fortpflanzung ist damit nicht belegt.']]});
add('potenz','konkurrenz','Intra oder inter?','match','Ordne die Konkurrenzsituationen zu.',{options:['Intraspezifisch','Interspezifisch'],items:[['Zwei Waldkiefern konkurrieren um Wasser','Intraspezifisch','Beide gehören derselben Art an.'],['Waldkiefer und Rotbuche konkurrieren um Licht','Interspezifisch','Zwei verschiedene Arten nutzen dieselbe begrenzte Ressource.'],['Zwei Blaumeisen konkurrieren um einen Nistkasten','Intraspezifisch','Es konkurrieren Individuen derselben Art.'],['Kohlmeise und Blaumeise konkurrieren um Nahrung','Interspezifisch','Die Konkurrenz findet zwischen Arten statt.']]});
add('nische','nischenbegriffe','Ort, Ansprüche, Unterschiede','match','Ordne die Aussagen den Begriffen zu.',{options:['Lebensraum','Ökologische Nische','Nischenüberlappung','Nischendifferenzierung'],items:[['Beide Vogelarten leben im selben Garten','Lebensraum','Die Aussage beschreibt den Ort.'],['Gesamtheit der Umweltansprüche und -beziehungen','Ökologische Nische','Die Nische ist ein Wirkungsgefüge.'],['Beide Arten nutzen dieselben Samen am Futterhaus','Nischenüberlappung','Bei dieser Ressource überschneiden sich die Ansprüche.'],['Eine Art sucht häufiger außen an dünnen Zweigen, die andere an stärkeren Ästen','Nischendifferenzierung','Unterschiedliche Ressourcennutzung kann Konkurrenz verringern.']]});
add('nische','meisen','Nischenprofile rekonstruieren','match','Ordne die typischen Beobachtungen zu. Beachte: Es geht um Schwerpunkte, nicht um starre Grenzen.',{options:['Eher Kohlmeise','Eher Blaumeise','Beide Arten'],items:[['Kleiner und leichter; erreicht feine äußere Zweige gut','Eher Blaumeise','Der Körperbau ermöglicht diesen Nutzungsschwerpunkt.'],['Sucht häufiger auch am Boden und an kräftigen Ästen','Eher Kohlmeise','Die größere Kohlmeise nutzt diese Bereiche häufiger.'],['Kann Sonnenblumenkerne am Futterhaus nutzen','Beide Arten','Die Nahrungsspektren überlappen.'],['Passt durch eine Nistkastenöffnung von etwa 26–28 mm','Eher Blaumeise','Die größere Kohlmeise passt nicht durch diese kleine Öffnung.']]});
add('nische','umbau','Ein Garten wird vereinheitlicht','multi','Im Garten werden feine äußere Zweige entfernt und nur noch Nistkästen mit 32-mm-Öffnungen angeboten. Wähle alle begründeten Folgerungen.',{choices:[['Die Blaumeise verliert einen typischen Bereich ihrer Nahrungssuche.',true,'Feine äußere Zweige sind für sie besonders gut nutzbar.'],['Die Überlappung beim Zugang zu Nistkästen kann zunehmen.',true,'Beide Arten können die größeren Öffnungen nutzen.'],['Die Blaumeise wird zwangsläufig vollständig aussterben.',false,'Dafür fehlen Daten zu Ausweichmöglichkeiten und Bestandsentwicklung.'],['Unterschiedliche Ressourcenangebote können Koexistenz begünstigen.',true,'Sie können die Überlappung begrenzter Ressourcen reduzieren.']]});
add('standort','pflanzen','Nektar, Pollen oder keines von beiden?','match','Ordne die sechs Pflanzen nach dem Nahrungsangebot aus den Profilen zu.',{options:['Nektar und Pollen','Pollen, aber kein Nektar','Weder Nektar noch Pollen'],items:[['Gänseblümchen','Nektar und Pollen','Das Angebot besteht nur, wenn Blüten vorhanden sind.'],['Breitwegerich','Pollen, aber kein Nektar','Er wird vorwiegend windbestäubt; Bienen können Pollen sammeln.'],['Echter Wurmfarn','Weder Nektar noch Pollen','Farne bilden Sporen, keine Blüten und keinen Pollen.'],['Weißklee','Nektar und Pollen','Blütenstände können durch Mahd entfernt werden.'],['Kleine Braunelle','Nektar und Pollen','Ihre Blütentriebe müssen stehen bleiben.'],['Geflecktes Lungenkraut','Nektar und Pollen','Es ergänzt das Angebot im Frühjahr.']]});
add('standort','pflege','Eine Maßnahme auswählen','scenario','Die Mitte der Rasenfläche muss als Pausenfläche erhalten bleiben. Welche der folgenden Maßnahmen erfüllt die Kriterien Standorteignung, Blütenangebot und Nutzung am besten?',{material:siteTable,choices:[['Gesamte Rasenfläche mit Wurmfarn bepflanzen','Der Wurmfarn passt schlecht zur offenen, mäßig trockenen Fläche und bietet weder Nektar noch Pollen. Außerdem geht die Pausenfläche verloren.'],['Sonnigen Randstreifen mit vorhandenen Blütenpflanzen abschnittsweise später mähen; Mitte weiter nutzen','Die Maßnahme lässt Blüten stehen und erhält die Nutzung. Prüfe zusätzlich Bodenfeuchte, Artenbestand und die Wirkung auf hohe Gräser.'],['Überall unverändert alle zwei Wochen kurz mähen','Das erhält die Nutzung, kann aber weiterhin Blüten entfernen und verbessert das Nahrungsangebot nicht gezielt.']],answer:1});
add('standort','messdaten','Befund oder unzulässiger Schluss?','multi','Wähle alle Aussagen, die sich mit den Standortdaten begründen lassen.',{material:siteTable,choices:[['A war um 12 Uhr heller und wärmer als B.',true,'42.000 statt 3.500 Lux und 22 statt 17 °C belegen dies für den Messzeitpunkt.'],['Der Nährstoffgehalt wurde an beiden Standorten bestimmt.',false,'Die Nährstoffversorgung wurde ausdrücklich nicht untersucht.'],['B ist an jedem Tag des Jahres gleich dunkel.',false,'Vor Laubaustrieb ist B heller; zudem ändern sich Wetter und Sonnenstand.'],['Mahdtoleranz garantiert kein ununterbrochenes Blütenangebot.',true,'Blätter können überleben, während Blüten abgeschnitten werden.']]});
add('symbiose','warnkette','Wie gelangt die Warnung zum Krebs?','order','Bringe die Vorgänge in die richtige Reihenfolge.',{items:['Gefahr erscheint in der Umgebung.','Die Grundel erkennt die Gefahr mit ihren Augen.','Die Grundel führt zitternde Bewegungen aus.','Der Krebs nimmt die Bewegung über den Fühlerkontakt wahr.','Der Krebs kann sich in die Höhle zurückziehen.'],explanation:'Das Signal wird von der Grundel über Bewegung und Körperkontakt übertragen. Der Krebs muss die Gefahr dafür nicht selbst sehen.'});
add('symbiose','nutzen','Wer leistet was, wer profitiert?','match','Ordne die Aussagen dem passenden Tier zu.',{options:['Grundel','Knallkrebs','Beide'],items:[['Baut und unterhält die Höhle','Knallkrebs','Der Krebs bewegt Sand und kleine Gesteinsteilchen.'],['Erkennt Gefahren durch gutes Sehvermögen','Grundel','Die Grundel beobachtet die Umgebung.'],['Erhält Warninformationen über einen Fühler','Knallkrebs','Er hält Körperkontakt zur Grundel.'],['Kann die Höhle als Rückzugsort nutzen','Beide','Die Höhle schützt beide Tiere.']]});
add('symbiose','bildbeweis','Was zeigt ein Bild wirklich?','multi','Ein Bild zeigt Grundel und Krebs mit Fühlerkontakt am Höhleneingang. Wähle alle fachlich tragfähigen Aussagen.',{choices:[['Das Bild kann räumliche Nähe und Kontakt zeigen.',true,'Diese Merkmale sind im Bild darstellbar.'],['Das Bild allein beweist die Übertragung einer Warnung.',false,'Dafür sind Beobachtungen eines zeitlichen Ablaufs nötig.'],['Für Symbiose muss ein Nutzen für beide Partner begründet werden.',true,'Ein Zusammenleben allein reicht nicht.'],['Der Höhlenbau und die Warnfunktion erklären unterschiedliche Vorteile.',true,'Die Grundel erhält Schutzraum, der Krebs Warninformationen.']]});
add('parasitismus','asselkette','Vom Anheften zum Gewebeschaden','order','Ordne die Schritte der im Material beschriebenen Erklärung.',{items:['Die Assel heftet sich an die Zunge.','Die Blutversorgung des Zungengewebes wird geschädigt.','Das Gewebe erhält weniger Sauerstoff und Nährstoffe.','Das Zungengewebe verkümmert.','Die Assel bleibt am Zungenstumpf und Mundboden befestigt.'],explanation:'Die Kette gibt die gängige Erklärung des Unterrichtsmaterials wieder. Hakenförmige Beinenden ermöglichen die Befestigung.'});
add('parasitismus','belege','Befund, Vermutung oder offene Frage?','match','Ordne die Aussagen aus dem Assel-Material ein.',{options:['Beobachteter Befund','Begründete Vermutung','Offene Frage','Nicht belegte Behauptung'],items:[['Zwei befallene Fische hatten trotz starkem Zungenverlust Nahrung aufgenommen.','Beobachteter Befund','Dies wurde in der beschriebenen Untersuchung festgestellt.'],['Die Assel kann einen Teil der mechanischen Funktion ersetzen.','Begründete Vermutung','Die Nahrungsaufnahme trotz Zungenverlust stützt diese Deutung.'],['Wovon ernährt sich die erwachsene Assel genau?','Offene Frage','Die genaue Ernährung ist nicht abschließend geklärt.'],['Befallene Fische leben besser als gesunde Fische.','Nicht belegte Behauptung','Ein Vorteil gegenüber gesunden Fischen wurde nicht nachgewiesen.']]});
add('parasitismus','beziehungen','Beziehungen mit Vorzeichen einordnen','match','Ordne die Wirkungen zu. Das erste Vorzeichen gehört jeweils zum zuerst genannten Partner.',{options:['+/+','+/−','−/−'],items:[['Grundel / Knallkrebs','+/+','Beide erhalten einen begründbaren Nutzen.'],['Assel / Fisch','+/−','Die Assel profitiert; der Fisch erleidet Gewebeschaden.'],['Waldkiefer / Rotbuche bei Konkurrenz','−/−','Beide werden gegenüber dem Wachstum allein beeinträchtigt, aber nicht gleich stark.']]});

const q=(title,prompt,solution,afb)=>({title,prompt,solution,afb});
GK.exams=[
{id:'bohnen',topic:'toleranz',title:'Wie viel Wasser ist günstig?',desc:'Toleranzkurven auswerten, Standorte einordnen und eine Behauptung beurteilen.',source:'Aufgaben neu formuliert auf Grundlage von AB 2; unveränderte didaktische Modelldaten.',materials:[['Material 1 · Ein kontrollierter Feuchteversuch',`<p>Gleich alte Bohnenpflanzen wachsen vier Wochen bei konstant gehaltener Bodenfeuchtigkeit. Licht, Temperatur, Boden und Nährstoffangebot sind gleich. Je Feuchtestufe werden mehrere Pflanzen untersucht. Die Feuchte bezeichnet den wassergefüllten Anteil des Porenraums. Gemessen wird der mittlere Zuwachs der Trockenmasse.</p>${beans()}${beanTable}`],['Material 2 · Längere Beobachtung',`<p>Weitere Pflanzen derselben Versuchsgruppen werden bis zur möglichen Fruchtbildung beobachtet. Unter 15 % und über 95 % sterben sie dauerhaft ab. Bei 15–25 % sowie 85–95 % überleben sie, bilden aber keine keimfähigen Samen. Bei mehr als 25 % und weniger als 85 % sind Wachstum und keimfähige Samen möglich.</p><p>Auch Wurzeln benötigen Sauerstoff für die Zellatmung. Sauerstoff gelangt über luftgefüllte Poren im Boden zu ihnen.</p>`]],questions:[q('Kurvenverlauf','Beschreiben Sie den Verlauf in Material 1. Belegen Sie Anstieg, Maximum und Abfall mit Zahlenwerten.','Der Zuwachs steigt von 0 g bei 15 % über 1,2 g bei 40 % auf 2,5 g bei 60 %. Danach fällt er über 1,2 g bei 80 % auf 0 g bei 95 %. Das gemessene Wachstumsoptimum liegt bei 60 % Bodenfeuchte.','I'),q('Toleranz und Fortpflanzung','Ermitteln Sie mit Material 2 Minimum, Maximum und beide Pessima. Erklären Sie, warum diese Angaben nicht allein aus Material 1 folgen.','Minimum: 15 %, Maximum: 95 %. Pessima: 15–25 % und 85–95 %. Dort überleben Pflanzen, bilden aber keine keimfähigen Samen. Material 1 erfasst nur Trockenmassezuwachs über vier Wochen; es misst weder dauerhafte Überlebensfähigkeit noch Samenbildung.','II'),q('Standorte einordnen','Vergleichen Sie anhand beider Materialien Standorte mit 20 %, 60 % und 90 % Bodenfeuchte hinsichtlich Wachstum und Fortpflanzung. Erläutern Sie, an welchem Standort sich ein Bestand unter den Modellbedingungen durch keimfähige Samen erneuern kann.','20 % liegen im unteren, 90 % im oberen Pessimum. Die Pflanzen überleben dort, bilden aber keine keimfähigen Samen; bei 90 % ist der Zuwachs mit 0,1 g sehr gering. 60 % liegen am gemessenen Wachstumsoptimum von 2,5 g und im Fortpflanzungsbereich. Dort ist die Erneuerung durch keimfähige Samen möglich. In den Pessima ist Überleben einzelner Pflanzen nicht mit erfolgreicher Fortpflanzung gleichzusetzen.','II'),q('Eine Behauptung beurteilen','Beurteilen Sie die Aussage „Je mehr Wasser, desto besser wachsen Bohnen“. Beziehen Sie beide Materialien ein.','Die pauschale Aussage ist falsch. Oberhalb des gemessenen Optimums von 60 % sinkt der Zuwachs, etwa auf 0,1 g bei 90 %. Hohe Wassersättigung verringert luftgefüllten Porenraum; dadurch kann die Sauerstoffversorgung der Wurzeln und ihre Zellatmung eingeschränkt werden. Material 2 zeigt zudem fehlende Samenbildung im oberen Pessimum und Tod oberhalb von 95 %. Der Sauerstoffmangel ist eine plausible Erklärung, wurde im Versuch aber nicht direkt gemessen.','III')]},
{id:'wald',topic:'potenz',title:'Waldkiefer und Rotbuche',desc:'Konkurrenzdaten und langfristiges Vorkommen gemeinsam deuten.',source:'Aufgaben neu formuliert nach AB 3. Alle Wachstums- und Häufigkeitsangaben sind didaktisch modelliert.',materials:[['Material 1 · Getrennte und gemeinsame Kultur',`<p>Junge Bäume wachsen bei sechs konstanten Bodenfeuchten getrennt oder gemeinsam. Licht, Temperatur, Nährstoffangebot und Versuchsdauer sind vergleichbar. Gemessen wird die relative Wuchsleistung auf einer Skala von 0 bis 10. Diese Messgröße zeigt nicht unmittelbar Fortpflanzung oder dauerhaftes Überleben.</p>${pineTable}<figure>${chart([15,30,45,60,75,90],[{label:'Kiefer allein',values:[3,6,9,10,8,4],color:'#087c88'},{label:'Kiefer mit Buche',values:[3,5,3,1,2,4],color:'#a86d32'}],10,'Relative Wuchsleistung (0–10)','Bodenfeuchtigkeit in %')}<figcaption>Wuchsleistung der Kiefer, Werte aus der Tabelle. Didaktisch modelliert.</figcaption></figure>`],['Material 2 · Langjährige Modellkartierung',table(['Bodenfeuchte (%)',15,30,45,60,75,90],[['Kiefer','häufig','häufig','selten','selten','selten','häufig'],['Buche','fehlt','selten','häufig','sehr häufig','häufig','fehlt']])+'<p>Erfasst werden etablierte Bestände mit Altbäumen und Jungpflanzen. Die Kartierung liefert damit Hinweise auf dauerhaftes Überleben und erfolgreiche Fortpflanzung unter natürlichen Konkurrenzbedingungen.</p>']],questions:[q('Datenvergleich','Vergleichen Sie mit Material 1 die Wuchsleistung der Kiefer allein und mit Buche. Gehen Sie auf 15 %, 60 % und 90 % Bodenfeuchte ein.','Bei 15 % beträgt die Leistung in beiden Ansätzen 3, bei 90 % jeweils 4. Bei 60 % wächst die Kiefer allein mit dem Wert 10, mit Buche nur mit 1. Der Rückgang ist im mittleren Feuchtebereich deutlich, an den beiden Randstufen fehlt er.','II'),q('Konkurrenz erklären','Erklären Sie die unterschiedliche Wirkung der Mischkultur auf beide Arten bei 60 % Bodenfeuchte. Beziehen Sie die Daten beider Arten ein.','Kiefer und Buche nutzen begrenzte Ressourcen gemeinsam; es liegt interspezifische Konkurrenz vor. Die Kiefer fällt von 10 auf 1, die Buche nur von 10 auf 9. Dies spricht für eine stärkere Konkurrenzwirkung auf die Kiefer und eine höhere Konkurrenzstärke der Buche unter diesen Bedingungen. Welche einzelne Ressource entscheidend ist, belegen die Daten nicht.','II'),q('Vorkommen deuten','Erklären Sie mit beiden Materialien, weshalb die Kiefer im Modellwald an den Randstandorten häufiger ist als bei 60 % Bodenfeuchte.','Allein wächst die Kiefer bei 60 % am stärksten. Dort wird ihre Leistung durch Buche aber stark vermindert; die Kartierung zeigt eine sehr häufige Buche und seltene Kiefer. Bei 15 und 90 % fehlt die Buche, sodass die Kiefer trotz geringerer Wuchsleistung ohne diesen Konkurrenten häufiger vorkommen kann. Häufigkeit ist somit kein direkter Indikator des physiologischen Optimums.','II'),q('Aussagekraft beurteilen','Beurteilen Sie die Aussage „Die Wachstumstabelle bestimmt exakt die ökologische Potenz der Kiefer“. Berücksichtigen Sie Material 2.','Die Aussage geht zu weit. Ökologische Potenz umfasst dauerhaftes Überleben und Fortpflanzung unter Konkurrenz. Die Tabelle misst nur Wuchsleistung während des Versuchs und nur bei sechs Feuchtestufen. Die langjährige Kartierung mit Jungpflanzen ergänzt wichtige Hinweise, liefert aber ebenfalls keine exakten Grenzwerte für alle Feuchtestufen und Umweltbedingungen.','III')]},
{id:'garten',topic:'nische',title:'Zwei Meisen in einem Garten',desc:'Nischenprofile vergleichen und Folgen eines Gartenumbaus abschätzen.',source:'Neu formuliertes Training nach AB 4 und dem Meisen-Lernprogramm; Nutzungsmuster didaktisch zusammengefasst.',materials:[['Material 1 · Beobachtungen im Garten',table(['Merkmal','Kohlmeise','Blaumeise'],[['Körperbau','Größer, schwerer','Kleiner, leichter'],['Nahrungssuche','Häufig kräftige innere Äste und Boden','Häufig feine äußere Zweige und Blätter'],['Nahrung','Insekten, auch größere Larven; im Winter Samen','Häufig kleine Insekten und Spinnen; auch Samen'],['Zugang zum Nistkasten','32-mm-Öffnung geeignet','26–28-mm-Öffnung geeignet; auch größere Öffnungen nutzbar']])+'<p>Die Angaben beschreiben typische Schwerpunkte. Beide Arten wurden an derselben Futterstelle beobachtet. Die verfügbaren Nistplätze sind begrenzt.</p>'],['Material 2 · Geplanter Umbau','<p>Ein großer Teil der feinen äußeren Zweige soll entfernt werden. Alle Nistkästen sollen künftig 32-mm-Öffnungen besitzen. Zusätzlich sollen in einem anderen Gartenbereich neue Sträucher gepflanzt werden. Über deren spätere Nutzung liegen noch keine Beobachtungen vor.</p>']],questions:[q('Begriffe anwenden','Erläutern Sie an Material 1 den Unterschied zwischen gemeinsamem Lebensraum und ökologischer Nische.','Der Garten ist der gemeinsame Lebensraum. Die Nische umfasst die jeweiligen Umweltansprüche und Beziehungen. Trotz desselben Ortes unterscheiden sich typische Nahrungssuchbereiche, Beutegrößen und der Zugang zu kleinen Nistöffnungen. Beide Arten können daher unterschiedliche Nischen besitzen.','II'),q('Koexistenz erklären','Erklären Sie mit drei Angaben aus Material 1, wodurch Konkurrenz verringert werden kann.','Der kleinere Körper der Blaumeise ermöglicht die Nutzung feiner äußerer Zweige, während die Kohlmeise häufiger kräftige Äste nutzt. Unterschiedliche Beutegrößen können die Überlappung bei Nahrung verringern. Kleine Nistöffnungen sind nur für die Blaumeise zugänglich. Diese Nischendifferenzierung kann Konkurrenz reduzieren; vollständig aufgehoben ist sie wegen gemeinsamer Nahrung und teilweise gemeinsamer Nistplätze nicht.','II'),q('Folgen ableiten','Leiten Sie aus den Materialien zwei mögliche Folgen des Umbaus für die Konkurrenz ab.','Der Verlust feiner Zweige kann die typische Nahrungssuche der Blaumeise einschränken und die Überlappung in verbleibenden Bereichen erhöhen. Nur noch große Nistöffnungen machen alle angebotenen Kästen für beide Arten zugänglich; bei begrenzten Plätzen kann die Konkurrenz zunehmen. Neue Sträucher könnten Ausweichmöglichkeiten schaffen, deren Nutzung ist aber noch offen.','II'),q('Prognose beurteilen','Beurteilen Sie die Behauptung „Nach dem Umbau verschwindet die Blaumeise sicher“. Begründen Sie anhand der Nischenprofile, welche Veränderungen sie benachteiligen und welche Ausweichmöglichkeiten bestehen könnten.','Die Behauptung ist nicht ausreichend belegt. Das Material stützt mögliche Konkurrenzzunahme, beweist aber keine vollständige Verdrängung. Ausweichressourcen, Nahrungsangebot und Nutzung der neuen Sträucher sind unbekannt. Die kleineren Körpermaße der Blaumeise ermöglichen weiterhin andere Nutzungsschwerpunkte als bei der Kohlmeise, sofern geeignete feine Zweige und Nahrung erhalten bleiben oder in den neuen Sträuchern entstehen. Mehr Überlappung kann Konkurrenz verstärken, bedeutet aber nicht automatisch vollständigen Konkurrenzausschluss.','III')]},
{id:'bienen',topic:'standort',title:'Eine Fläche für die Bienen-AG',desc:'Standortdaten und Pflanzenprofile auswerten, eine Maßnahme abwägen.',source:'Standortangaben und Pflanzenprofile aus AB 5, gekürzt; Aufgaben für den Lernraum neu formuliert.',materials:[['Material 1 · Zwei Schulflächen',siteTable],['Material 2 · Pflanzenprofile',plants],['Material 3 · Rahmen der Entscheidung','<p>Die Bienen-AG möchte über mehrere Monate Blüten anbieten. Die Mitte der Rasenfläche muss als Pausenfläche erhalten bleiben; ein Randstreifen kann anders gepflegt werden. Die Laubbäume bleiben erhalten. Es gibt keine zusätzlichen Messungen zur Nährstoffversorgung. Die Pflege muss mit dem vorhandenen Schulbetrieb vereinbar sein.</p>']],questions:[q('Standorte vergleichen','Vergleichen Sie die Standorte A und B anhand von Licht, Bodenfeuchte und Nutzung in Material 1.','A ist am Messzeitpunkt mit 42.000 Lux heller als B mit 3.500 Lux; B wird im Frühjahr vor Laubaustrieb heller als im belaubten Sommer. A ist mäßig trocken, B mäßig feucht. A wird regelmäßig gemäht und als Pausenfläche betreten, B selten betreten und nicht regelmäßig gemäht.','I–II'),q('Pflanzenauswahl begründen','Begründen Sie mit Material 1 und 2 die Eignung von Weißklee für A und Lungenkraut für B. Nennen Sie je eine Unsicherheit oder notwendige Bedingung.','Weißklee passt zu hellen Standorten und verträgt Mahd grundsätzlich. Auf A muss aber ausreichend Feuchte vorhanden sein; Blütenstände dürfen nicht ständig abgeschnitten werden. Lungenkraut passt zu dem halbschattigen bis schattigen, humusreichen und mäßig feuchten Standort B und kann vor Laubaustrieb blühen. Die Nährstoffversorgung ist noch zu prüfen; längere Trockenphasen könnten ungünstig sein.','II'),q('Überleben und Blütenangebot','Erklären Sie anhand von Weißklee und Wurmfarn, warum eine überlebende Pflanze nicht automatisch Nahrung für Bienen bereitstellt.','Weißklee kann mit seinen kriechenden Trieben Mahd überstehen, während Blütenstände abgeschnitten werden; ohne Blüten liefert er dann keinen Nektar oder Pollen. Wurmfarn kann unter den Bäumen gut wachsen, bildet als Sporenpflanze aber überhaupt keine Blüten, keinen Nektar und keinen Pollen.','II'),q('Maßnahme beurteilen','Entwickeln und beurteilen Sie anhand der Materialien einen Vorschlag. Berücksichtigen Sie Standorteignung, Blütezeit, Pflege und Nutzung. Nennen Sie einen Zielkonflikt und eine offene Frage.','Ein möglicher Vorschlag: Einen sonnigen Randstreifen mit vorhandenen Gänseblümchen, Weißklee und Kleiner Braunelle abschnittsweise später mähen, sodass Blüten erhalten bleiben. Die Mitte bleibt kurz und nutzbar. Lungenkraut kann unter Bäumen ein Frühjahrsangebot ergänzen. Weißklee und Braunelle tragen vor allem von Mai bzw. Juni bis September bei; die Profile garantieren keine lückenlose tatsächliche Blüte. Zielkonflikt: längere Blüte versus Pflegeaufwand und nutzbare Fläche; bei vollständigem Mahdverzicht können hohe Gräser konkurrenzstark werden. Zu prüfen sind Feuchte, Nährstoffe und tatsächlicher Blütenbesuch. Andere materialgestützt begründete Vorschläge sind möglich.','III')]},
{id:'partner',topic:'parasitismus',title:'Zusammenleben: Nutzen oder Schaden?',desc:'Symbiose und Parasitismus vergleichen und die Aussagekraft von Befunden prüfen.',source:'AB 6 und 7 sowie zugehörige DOCX-Materialien; dortige Fachquellen: Australian Museum (McGrouther, 2020), Brusca & Gilligan (1983), University of Texas Biodiversity Center (2021).',materials:[['Material 1 · Grundel und Knallkrebs','<p>Der Knallkrebs baut und unterhält eine Höhle, die beide Tiere als Rückzugsort nutzen. Er sieht schlecht. Die Grundel beobachtet mit ihren gut entwickelten Augen die Umgebung. Der Krebs hält beim Verlassen der Höhle über einen Fühler Kontakt zum Fisch. Bei Gefahr führt die Grundel zitternde Bewegungen aus, die der Krebs über den Kontakt wahrnehmen kann.</p>'],['Material 2 · Assel und Schnapperfisch','<p>Die Assel <i>Cymothoa exigua</i> heftet sich mit hakenförmigen Beinenden im Maul an. Nach der gängigen Erklärung wird die Blutversorgung der Zunge geschädigt. Das Gewebe verkümmert; die Assel bleibt am Zungenstumpf und Mundboden befestigt. Als Nahrung werden Blut und Schleim beschrieben; die genaue Ernährung im erwachsenen Stadium ist nicht abschließend geklärt.</p><p>Bei zwei untersuchten befallenen Fischen fehlten mehr als 90 % der Zunge. Beide hatten dennoch Nahrung aufgenommen. Die Forschenden vermuteten eine teilweise mechanische Ersatzfunktion der Assel. Ein Vorteil befallener gegenüber gesunden Fischen wurde damit nicht nachgewiesen.</p>']],questions:[q('Nutzen erklären','Erklären Sie für beide Partner in Material 1 jeweils einen Nutzen und ordnen Sie die Beziehung begründet ein.','Die Grundel nutzt die vom Krebs gebaute und unterhaltene Höhle als Schutzraum. Der schlecht sehende Krebs erhält Warninformationen über den Fühlerkontakt zur gut sehenden Grundel. Beide profitieren; dies ist Symbiose im engeren Sinn (+/+).','II'),q('Wirkungskette darstellen','Stellen Sie mit Material 2 die Erklärung des Zungenverlusts als beschriftete Pfeilkette dar.','Anheften der Assel → Schädigung der Blutversorgung → verringerte Sauerstoff- und Nährstoffversorgung des Zungengewebes → Verkümmern der Zunge. Die Assel bleibt am Zungenstumpf und Mundboden befestigt. Die Kette gibt die gängige Erklärung wieder.','II'),q('Befund und Deutung unterscheiden','Unterscheiden Sie in Material 2 einen beobachteten Befund, eine daraus abgeleitete Vermutung und eine offene Frage.','Befund: Zwei befallene Fische hatten trotz Verlusts von mehr als 90 % der Zunge Nahrung aufgenommen. Vermutung: Die Assel übernimmt einen Teil der mechanischen Funktion beim Festhalten von Nahrung. Offen: die genaue Ernährung der erwachsenen Assel. Die Ersatzfunktion darf nicht als unmittelbar beobachteter Gesamtnutzen formuliert werden.','II'),q('Einordnung beurteilen','Beurteilen Sie die Aussage „Die Assel ersetzt die Zunge, also liegt wie bei Grundel und Knallkrebs Symbiose vor“. Verwenden Sie eine geeignete Vergleichssituation.','Die Aussage ist nicht tragfähig. Eine mögliche Ersatzfunktion belegt keinen Vorteil gegenüber einem gesunden Fisch ohne Assel. Der Verlust des Zungengewebes ist ein Schaden. Die Assel profitiert vom Wirt als Lebensraum und Nahrungsquelle, während dieser geschädigt wird: Parasitismus (+/−). Bei Grundel und Knallkrebs ist dagegen für beide ein Nutzen begründet. Dass der befallene Fisch weiter frisst oder lebt, macht die Beziehung nicht zur Symbiose.','III')]}
];

